34	export function CommandPalette({ nav }: { nav: NavEntry[] }) {
35	  const [open, setOpen] = useState(false);
36	  const [q, setQ] = useState("");
37	  const [results, setResults] = useState<Result[]>([]);
38	  const [active, setActive] = useState(0);
39	  const router = useRouter();
40	  const inputRef = useRef<HTMLInputElement>(null);
41	  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
42	  // Where focus was when the palette opened, so closing it (Escape, click-away,
43	  // navigation) returns focus to the ⌘K trigger instead of dropping it to the
44	  // top of the document.
45	  const restoreFocus = useRef<HTMLElement | null>(null);
46	
47	  useEffect(() => {
48	    const onKey = (e: KeyboardEvent) => {
49	      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
50	        e.preventDefault();
51	        setOpen((v) => !v);
52	      }
53	      if (e.key === "Escape") setOpen(false);
54	    };
55	    window.addEventListener("keydown", onKey);
56	    return () => window.removeEventListener("keydown", onKey);
57	  }, []);
58	
59	  useEffect(() => {
60	    if (open) {
61	      restoreFocus.current = (document.activeElement as HTMLElement) ?? null;
62	      setQ("");
63	      setResults([]);
64	      setActive(0);
65	      setTimeout(() => inputRef.current?.focus(), 30);
66	    } else {
67	      restoreFocus.current?.focus?.();
68	      restoreFocus.current = null;
69	    }
70	  }, [open]);
71	
72	  const navMatches: Result[] = q.length > 0
73	    ? nav
74	        .filter((n) => n.label.toLowerCase().includes(q.toLowerCase()))
75	        .slice(0, 5)
76	        .map((n) => ({ type: "page", label: n.label, sub: n.section, href: n.href }))
77	    : nav.slice(0, 7).map((n) => ({ type: "page", label: n.label, sub: n.section, href: n.href }));
78	
79	  useEffect(() => {
80	    if (debounce.current) clearTimeout(debounce.current);
81	    if (q.length < 2) {
82	      setResults([]);
83	      return;
84	    }
85	    debounce.current = setTimeout(async () => {
86	      try {
87	        const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`);
88	        const json = await res.json();
89	        setResults(json.results ?? []);
90	      } catch {
91	        setResults([]);
92	      }
93	    }, 180);
94	  }, [q]);
95	
96	  const all = [...navMatches, ...results];
97	
98	  const go = useCallback(
99	    (href: string) => {
100	      setOpen(false);
101	      router.push(href);
102	    },
103	    [router]
104	  );
105	
106	  if (!open) return null;
107	
108	  return (
109	    <div
110	      className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 p-4 pt-[12vh] backdrop-blur-sm"
111	      onClick={() => setOpen(false)}
112	    >
113	      <div
114	        role="dialog"
115	        aria-modal="true"
116	        aria-label="Command palette"
117	        className="glass w-full max-w-xl overflow-hidden shadow-2xl animate-fade-up"
118	        onClick={(e) => e.stopPropagation()}
119	      >
120	        <div className="flex items-center gap-3 border-b border-white/[0.08] px-4 py-3">
121	          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" strokeWidth="2">
122	            <circle cx="11" cy="11" r="7" />
123	            <path d="M21 21l-4-4" />
124	          </svg>
125	          <input
126	            ref={inputRef}
127	            aria-label="Search servers, hosting, websites, email, domains, tickets and pages"
128	            className="w-full bg-transparent text-sm outline-none placeholder:text-slate-500"
129	            placeholder="Search servers, hosting, email, domains, tickets…"
130	            value={q}
131	            onChange={(e) => {
132	              setQ(e.target.value);
133	              setActive(0);
134	            }}
135	            onKeyDown={(e) => {
136	              if (e.key === "ArrowDown") {
137	                e.preventDefault();
138	                setActive((a) => Math.min(a + 1, all.length - 1));
139	              }
140	              if (e.key === "ArrowUp") {
141	                e.preventDefault();
142	                setActive((a) => Math.max(a - 1, 0));
143	              }
144	              if (e.key === "Enter" && all[active]) go(all[active].href);
145	            }}
146	          />
147	          <span className="kbd">esc</span>
148	        </div>
149	        <div className="max-h-[50vh] overflow-y-auto p-2">
150	          {all.length === 0 ? (
151	            <p className="px-3 py-6 text-center text-sm text-slate-500">No results.</p>
152	          ) : (
153	            all.map((r, i) => {
154	              // Emit a group header whenever the type changes. The flat order
155	              // matches the visual group order, so this reads as clean sections
156	              // while keyboard nav still walks a single top-to-bottom list.
157	              const showHeader = i === 0 || all[i - 1].type !== r.type;
158	              return (
159	                <div key={`${r.type}-${r.href}-${i}`}>
160	                  {showHeader && (
161	                    <p className="px-3 pb-1 pt-2 text-[10px] font-semibold uppercase tracking-wider text-slate-500">
162	                      {typeLabels[r.type] ?? r.type}
163	                    </p>
164	                  )}
165	                  <button
166	                    className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm transition-colors ${
167	                      i === active ? "bg-brand-500/20 text-white" : "text-slate-300 hover:bg-white/[0.05]"
168	                    }`}
169	                    onMouseEnter={() => setActive(i)}
170	                    onClick={() => go(r.href)}
171	                  >
172	                    <span className="w-5 text-center text-xs opacity-70">{typeIcons[r.type] ?? "→"}</span>
173	                    <span className="flex-1 truncate">{r.label}</span>
174	                    {r.sub && <span className="truncate text-xs text-slate-500">{r.sub}</span>}
175	                  </button>
176	                </div>
177	              );
178	            })
179	          )}
180	        </div>
181	      </div>
182	    </div>
183	  );
184	}
